# Dockerfile
FROM ubuntu:jammy
RUN apt update -y && \
    apt install -y \
    python3.10-dev python3.10-distutils python3-pip
RUN pip install requests
```

```python
# main.py
import logging
import os
import sys
import warnings
from concurrent import futures

import requests
import urllib3.poolmanager

WORKER_COUNT = 128


def test_requests():
    session = requests.Session()
    for i in range(48):
        session.get('https://google.com')


def test_requests_threaded():
    executor = futures.ThreadPoolExecutor(max_workers=WORKER_COUNT)

    def get():
        session = requests.Session()
        return session.get('https://google.com')

    return [
        future.result()
        for future in futures.as_completed([executor.submit(get) for i in range(48)])
    ]


def test_urllib3_threaded():
    executor = futures.ThreadPoolExecutor(max_workers=WORKER_COUNT)
    connection_manager = urllib3.poolmanager.PoolManager(num_pools=WORKER_COUNT, maxsize=WORKER_COUNT)

    def get(connection_manager):
        return connection_manager.request('GET', 'https://google.com')

    return [
        future.result()
        for future in futures.as_completed([executor.submit(get, connection_manager) for i in range(48)])
    ]


tests = {
    "test_requests": test_requests,
    "test_requests_threaded": test_requests_threaded,
    "test_urllib3_threaded": test_urllib3_threaded,
}

if __name__ == "__main__":
    os.environ["SSLKEYLOGFILE"] = "/app/tls.log"
    # Enable all logging and warnings
    warnings.simplefilter("always")

    logging.basicConfig(level=logging.DEBUG)
    loggers = [logging.getLogger(name) for name in logging.root.manager.loggerDict]
    for logger in loggers:
        logger.setLevel(logging.DEBUG)
    try:

        tests[sys.argv[1]]()
    finally:
        with open(os.environ["SSLKEYLOGFILE"], "r", encoding="utf-8") as file:
            print(file.read())
```

```bash
docker build . -t requests-tls-repro
docker run --entrypoint=bash -v .:/app/ -it requests-tls-repro
$ cd /app/
$ python3 main.py test_requests
$ python3 main.py test_requests_threaded
$ python3 main.py test_urllib3_threaded
```

